{"content":"from units import celsius_to_fahrenheit, kelvin_to_fahrenheit, convert

def test_reproduce_issue():
    print(f"celsius_to_fahrenheit(100) = {celsius_to_fahrenheit(100)}")
    assert celsius_to_fahrenheit(100) == 212.0, f"Expected 212.0, got {celsius_to_fahrenheit(100)}"

    print(f"convert(100, 'celsius', 'fahrenheit') = {convert(100, 'celsius', 'fahrenheit')}")
    assert convert(100, 'celsius', 'fahrenheit') == 212.0, f"Expected 212.0, got {convert(100, 'celsius', 'fahrenheit')}"

    print("Testing absolute zero error raising...")
    try:
        celsius_to_fahrenheit(-300)
        print("celsius_to_fahrenheit(-300) did not raise ValueError")
    except ValueError:
        print("celsius_to_fahrenheit(-300) raised ValueError as expected")
    except Exception as e:
        print(f"celsius_to_fahrenheit(-300) raised unexpected exception: {type(e).__name__}: {e}")
    else:
        print("celsius_to_fahrenheit(-300) did not raise ValueError")

if __name__ == "__main__":
    try:
        test_reproduce_issue()
        print("Tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
